import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry conv_transpose3d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .s32 n_batches,
    .param .s32 in_channels,
    .param .s32 out_channels,
    .param .s32 in_depth,
    .param .s32 in_height,
    .param .s32 in_width,
    .param .s32 out_depth,
    .param .s32 out_height,
    .param .s32 out_width,
    .param .s32 kernel_size,
    .param .s32 has_bias
)
{
    .shared .align 16 .b8 smem_in[29376];
    .shared .align 16 .b8 smem_w[3456];
    .reg .pred %p0, %p1, %p_inb, %p_st1, %p_k3;
    .reg .pred %p_done, %p_ci, %p_kz, %p_ky, %p_kx;
    .reg .pred %p_zlo, %p_zhi, %p_ylo, %p_yhi, %p_xlo, %p_xhi, %p_bias, %p_wok, %p_al2, %p_vec, %p_sec;
    .reg .b32 %r_ntid, %r_ctaid, %r_tid0, %r_tid, %r_total, %r_tmp, %r_tmp2;
    .reg .b32 %r_ox, %r_oy, %r_oz, %r_co, %r_bn;
    .reg .b32 %r_N, %r_CI, %r_CO, %r_D, %r_H, %r_W, %r_DO, %r_HO, %r_WO, %r_K, %r_BIAS;
    .reg .b32 %r_ci, %r_kz, %r_ky, %r_kx, %r_z, %r_y, %r_x;
    .reg .b32 %r_off, %r_woff, %r_hw, %r_dhw, %r_chw;
    .reg .b32 %r_txT, %r_tyT, %r_txtile, %r_tytile, %r_oy0, %r_ox0, %r_ty, %r_tx;
    .reg .b32 %r_ci0, %r_chunk, %r_idx, %r_limit, %r_c, %r_rem, %r_r2, %r_row, %r_col;
    .reg .b32 %r_shin, %r_shw, %r_ain, %r_sbase, %r_rowoff, %r_sidx, %r_widx;
    .reg .b32 %r_co0, %r_cog, %r_COG, %r_j, %r_wbase, %r_b, %r_wt;
    .reg .b32 %r_g, %r_soff, %r_ybase, %r_xbase, %r_zD, %r_HWc, %r_dg0, %r_dg1;
    .reg .b32 %r_dg2, %r_dg3, %r_row0, %r_col0, %r_wrem, %r_wd1, %r_wtap0, %r_wrem0, %r_wd0;
    .reg .b32 %r_cw0, %r_cow, %r_srcsz, %r_wsz;
    .reg .b32 %r_buf, %r_ciend, %r_shins, %r_shws, %r_shinc, %r_shwc;
    .reg .b64 %xptr, %wptr, %bptr, %yptr, %addr, %waddr, %baddr, %yaddr;
    .reg .f32 %acc, %xv, %wv, %bv;
    .reg .f32 %a00, %a01, %a02, %a03, %a04, %a05, %a06, %a07;
    .reg .f32 %a10, %a11, %a12, %a13, %a14, %a15, %a16, %a17;
    .reg .f32 %v0, %v1, %v2, %v3;
    .reg .f32 %wv0, %wv1, %wv2, %wv3, %wv4, %wv5, %wv6, %wv7;
    ld.param.u64 %xptr, [x_ptr];
    ld.param.u64 %wptr, [w_ptr];
    ld.param.u64 %bptr, [b_ptr];
    ld.param.u64 %yptr, [y_ptr];
    ld.param.s32 %r_N, [n_batches];
    ld.param.s32 %r_CI, [in_channels];
    ld.param.s32 %r_CO, [out_channels];
    ld.param.s32 %r_D, [in_depth];
    ld.param.s32 %r_H, [in_height];
    ld.param.s32 %r_W, [in_width];
    ld.param.s32 %r_DO, [out_depth];
    ld.param.s32 %r_HO, [out_height];
    ld.param.s32 %r_WO, [out_width];
    ld.param.s32 %r_K, [kernel_size];
    ld.param.s32 %r_BIAS, [has_bias];
    setp.eq.s32 %p_k3, %r_K, 3;
    @!%p_k3 bra $D_setup;
    // ============================================================
    // Tiled path (K == 3, stride 1, pad 0): each CTA computes one
    // 32x16 output tile for a fixed (batch, out_z) and a GROUP of
    // 8 output channels.
    // Spatial register blocking: each thread computes TWO adjacent
    // output columns for all 8 output channels (16 accumulators
    // a00..a07/a10..a17), with fully unrolled 3x3x3 tap loops.
    // NEW: software-pipelined cp.async double buffering. The input-
    // channel reduction runs in 2-channel chunks; the shared input
    // patch (2 x 34x18x3 floats) and weights (2 x 27x8 floats) are
    // split into two half-buffers. While the FMA phase consumes the
    // previous chunk from one half-buffer, the next chunk is staged
    // into the other half via cp.async, using commit_group +
    // wait_group 1 so global-load latency overlaps compute instead
    // of serializing stage -> barrier -> compute on every chunk.
    // ============================================================
    mov.u32 %r_shin, smem_in;
    mov.u32 %r_shw, smem_w;
    mov.u32 %r_ctaid, %ctaid.x;
    mov.u32 %r_tid, %tid.x;
    add.s32 %r_txT, %r_WO, 31;
    shr.s32 %r_txT, %r_txT, 5;
    add.s32 %r_tyT, %r_HO, 15;
    shr.s32 %r_tyT, %r_tyT, 4;
    add.s32 %r_COG, %r_CO, 7;
    shr.s32 %r_COG, %r_COG, 3;
    rem.s32 %r_cog, %r_ctaid, %r_COG;
    div.s32 %r_tmp, %r_ctaid, %r_COG;
    rem.s32 %r_txtile, %r_tmp, %r_txT;
    div.s32 %r_tmp, %r_tmp, %r_txT;
    rem.s32 %r_tytile, %r_tmp, %r_tyT;
    div.s32 %r_tmp, %r_tmp, %r_tyT;
    rem.s32 %r_oz, %r_tmp, %r_DO;
    div.s32 %r_bn, %r_tmp, %r_DO;
    shl.b32 %r_co0, %r_cog, 3;
    shl.b32 %r_ox0, %r_txtile, 5;
    shl.b32 %r_oy0, %r_tytile, 4;
    shr.s32 %r_ty, %r_tid, 4;
    and.b32 %r_tx, %r_tid, 15;
    shl.b32 %r_b, %r_tx, 1;
    add.s32 %r_oy, %r_oy0, %r_ty;
    add.s32 %r_ox, %r_ox0, %r_b;
    setp.lt.s32 %p0, %r_oy, %r_HO;
    setp.lt.s32 %p1, %r_ox, %r_WO;
    and.pred %p_inb, %p0, %p1;
    add.s32 %r_tmp, %r_ox, 1;
    setp.lt.s32 %p1, %r_tmp, %r_WO;
    and.pred %p_st1, %p0, %p1;
    // ---- precompute staging constants once per CTA ----
    sub.s32 %r_ybase, %r_oy0, 2;
    sub.s32 %r_xbase, %r_ox0, 2;
    sub.s32 %r_zD, %r_oz, %r_D;
    mul.lo.s32 %r_HWc, %r_H, %r_W;
    mul.lo.s32 %r_dg0, %r_W, 7;
    add.s32 %r_dg0, %r_dg0, 18;
    add.s32 %r_dg1, %r_W, -34;
    mul.lo.s32 %r_tmp, %r_W, 18;
    add.s32 %r_tmp, %r_tmp, %r_HWc;
    neg.s32 %r_dg2, %r_tmp;
    mul.lo.s32 %r_tmp, %r_HWc, 3;
    mul.lo.s32 %r_tmp2, %r_D, %r_HWc;
    add.s32 %r_dg3, %r_tmp, %r_tmp2;
    div.s32 %r_row0, %r_tid, 34;
    mul.lo.s32 %r_tmp, %r_row0, 34;
    sub.s32 %r_col0, %r_tid, %r_tmp;
    setp.ge.s32 %p0, %r_tid, 216;
    selp.s32 %r_cw0, 1, 0, %p0;
    mul.lo.s32 %r_tmp, %r_cw0, 216;
    sub.s32 %r_wrem0, %r_tid, %r_tmp;
    shr.s32 %r_wtap0, %r_wrem0, 3;
    and.b32 %r_tmp, %r_wrem0, 7;
    add.s32 %r_cow, %r_co0, %r_tmp;
    setp.lt.s32 %p_wok, %r_cow, %r_CO;
    selp.b32 %r_wsz, 4, 0, %p_wok;
    add.s32 %r_tmp, %r_CO, -1;
    mul.lo.s32 %r_wd1, %r_tmp, 27;
    mul.lo.s32 %r_wd0, %r_CO, 27;
    add.s32 %r_wd0, %r_wd0, 5;
    mov.f32 %a00, 0f00000000;
    mov.f32 %a01, 0f00000000;
    mov.f32 %a02, 0f00000000;
    mov.f32 %a03, 0f00000000;
    mov.f32 %a04, 0f00000000;
    mov.f32 %a05, 0f00000000;
    mov.f32 %a06, 0f00000000;
    mov.f32 %a07, 0f00000000;
    mov.f32 %a10, 0f00000000;
    mov.f32 %a11, 0f00000000;
    mov.f32 %a12, 0f00000000;
    mov.f32 %a13, 0f00000000;
    mov.f32 %a14, 0f00000000;
    mov.f32 %a15, 0f00000000;
    mov.f32 %a16, 0f00000000;
    mov.f32 %a17, 0f00000000;
    mov.s32 %r_ci0, 0;
    mov.s32 %r_buf, 0;
    add.s32 %r_ciend, %r_CI, 2;
$L_chunk_loop:
    setp.lt.s32 %p0, %r_ci0, %r_ciend;
    @!%p0 bra $L_epilogue;
    // ---- pipelined staging: issue cp.async for chunk (ci0) into ----
    // ---- buffer r_buf while the previous chunk is being computed ----
    setp.lt.s32 %p0, %r_ci0, %r_CI;
    @!%p0 bra $L_stagedone;
    sub.s32 %r_chunk, %r_CI, %r_ci0;
    min.s32 %r_chunk, %r_chunk, 2;
    mul.lo.s32 %r_tmp, %r_buf, 14688;
    add.u32 %r_shins, %r_shin, %r_tmp;
    mul.lo.s32 %r_tmp, %r_buf, 1728;
    add.u32 %r_shws, %r_shw, %r_tmp;
    // ---- stage input patch (zero-filled halo) into shared ----
    // Incremental index update: each +256-element stride is folded into
    // (col,row,kz,c) carries with precomputed global-offset deltas, so the
    // staging loop needs no div/rem chains or full address recomputation.
    mul.lo.s32 %r_limit, %r_chunk, 7344;
    shl.b32 %r_soff, %r_tid, 2;
    mov.s32 %r_row, %r_row0;
    mov.s32 %r_col, %r_col0;
    mov.s32 %r_kz, 0;
    mul.lo.s32 %r_g, %r_bn, %r_CI;
    add.s32 %r_g, %r_g, %r_ci0;
    mul.lo.s32 %r_g, %r_g, %r_D;
    add.s32 %r_g, %r_g, %r_oz;
    mul.lo.s32 %r_g, %r_g, %r_H;
    add.s32 %r_g, %r_g, %r_ybase;
    mul.lo.s32 %r_g, %r_g, %r_W;
    add.s32 %r_g, %r_g, %r_xbase;
    mul.lo.s32 %r_tmp, %r_row0, %r_W;
    add.s32 %r_g, %r_g, %r_tmp;
    add.s32 %r_g, %r_g, %r_col0;
$L_ldloop:
    setp.lt.s32 %p0, %r_soff, %r_limit;
    @!%p0 bra $L_lddone;
    add.s32 %r_y, %r_row, %r_ybase;
    add.s32 %r_x, %r_col, %r_xbase;
    setp.lt.s32 %p0, %r_oz, %r_kz;
    setp.ge.s32 %p1, %r_zD, %r_kz;
    or.pred %p0, %p0, %p1;
    setp.lt.s32 %p1, %r_y, 0;
    or.pred %p0, %p0, %p1;
    setp.ge.s32 %p1, %r_y, %r_H;
    or.pred %p0, %p0, %p1;
    setp.lt.s32 %p1, %r_x, 0;
    or.pred %p0, %p0, %p1;
    setp.ge.s32 %p1, %r_x, %r_W;
    or.pred %p0, %p0, %p1;
    selp.b32 %r_srcsz, 0, 4, %p0;
    mul.wide.s32 %addr, %r_g, 4;
    add.u64 %addr, %xptr, %addr;
    add.u32 %r_ain, %r_shins, %r_soff;
    cp.async.ca.shared.global [%r_ain], [%addr], 4, %r_srcsz;
    add.s32 %r_soff, %r_soff, 1024;
    add.s32 %r_g, %r_g, %r_dg0;
    add.s32 %r_col, %r_col, 18;
    add.s32 %r_row, %r_row, 7;
    setp.lt.s32 %p0, %r_col, 34;
    @%p0 bra $L_adv1;
    add.s32 %r_col, %r_col, -34;
    add.s32 %r_row, %r_row, 1;
    add.s32 %r_g, %r_g, %r_dg1;
$L_adv1:
    setp.lt.s32 %p0, %r_row, 18;
    @%p0 bra $L_adv2;
    add.s32 %r_row, %r_row, -18;
    add.s32 %r_kz, %r_kz, 1;
    add.s32 %r_g, %r_g, %r_dg2;
$L_adv2:
    setp.lt.s32 %p0, %r_kz, 3;
    @%p0 bra $L_ldloop;
    mov.s32 %r_kz, 0;
    add.s32 %r_g, %r_g, %r_dg3;
    bra $L_ldloop;
$L_lddone:
    // ---- stage weights for 4 cin x 8 cout into shared ----
    // Layout is cout-fastest: smem_w[c*216 + tap*8 + j] so the compute
    // loop fetches all 8 output-channel weights with two ld.shared.v4.
    // The tap index advances by +5 per 256-element stride and j stays
    // fixed (40 = 5*8, 216 = 27*8), so no div/rem is needed here either.
    mul.lo.s32 %r_limit, %r_chunk, 864;
    shl.b32 %r_soff, %r_tid, 2;
    add.s32 %r_woff, %r_ci0, %r_cw0;
    mul.lo.s32 %r_woff, %r_woff, %r_CO;
    add.s32 %r_woff, %r_woff, %r_cow;
    mul.lo.s32 %r_woff, %r_woff, 27;
    add.s32 %r_woff, %r_woff, %r_wtap0;
    mov.s32 %r_wrem, %r_wrem0;
$L_wloop:
    setp.lt.s32 %p0, %r_soff, %r_limit;
    @!%p0 bra $L_wdone;
    mul.wide.s32 %addr, %r_woff, 4;
    add.u64 %addr, %wptr, %addr;
    add.u32 %r_ain, %r_shws, %r_soff;
    cp.async.ca.shared.global [%r_ain], [%addr], 4, %r_wsz;
    add.s32 %r_soff, %r_soff, 1024;
    add.s32 %r_woff, %r_woff, %r_wd0;
    add.s32 %r_wrem, %r_wrem, 40;
    setp.lt.s32 %p0, %r_wrem, 216;
    @%p0 bra $L_wloop;
    add.s32 %r_wrem, %r_wrem, -216;
    add.s32 %r_woff, %r_woff, %r_wd1;
    bra $L_wloop;
$L_wdone:
$L_stagedone:
    cp.async.commit_group;
    cp.async.wait_group 1;
    bar.sync 0;
    // ---- compute previous chunk (ci0-2) from the other half-buffer ----
    setp.lt.s32 %p0, %r_ci0, 2;
    @%p0 bra $L_compute_done;
    sub.s32 %r_chunk, %r_ciend, %r_ci0;
    min.s32 %r_chunk, %r_chunk, 2;
    mul.lo.s32 %r_tmp, %r_buf, 14688;
    add.u32 %r_shinc, %r_shin, 14688;
    sub.u32 %r_shinc, %r_shinc, %r_tmp;
    mul.lo.s32 %r_tmp, %r_buf, 1728;
    add.u32 %r_shwc, %r_shw, 1728;
    sub.u32 %r_shwc, %r_shwc, %r_tmp;
    @!%p_inb bra $L_compute_done;
    mov.s32 %r_c, 0;
$L_cloop:
    setp.lt.s32 %p0, %r_c, %r_chunk;
    @!%p0 bra $L_compute_done;
    mul.lo.s32 %r_sbase, %r_c, 1836;
    mul.lo.s32 %r_wbase, %r_c, 27;
    mov.s32 %r_kz, 0;
$L_kzloop:
    setp.lt.s32 %p0, %r_kz, 3;
    @!%p0 bra $L_kzdone;
    mul.lo.s32 %r_tmp, %r_kz, 612;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.lo.s32 %r_rowoff, %r_ty, 34;
    add.s32 %r_rowoff, %r_rowoff, %r_b;
    add.s32 %r_rowoff, %r_rowoff, %r_tmp;
    shl.b32 %r_off, %r_rowoff, 2;
    add.u32 %r_ain, %r_shinc, %r_off;
    mul.lo.s32 %r_tmp, %r_kz, 9;
    add.s32 %r_tmp, %r_tmp, %r_wbase;
    shl.b32 %r_tmp, %r_tmp, 5;
    add.u32 %r_wt, %r_shwc, %r_tmp;
    // ---- ky = 0 (patch row ty+2) ----
    ld.shared.v2.f32 {%v0, %v1}, [%r_ain+272];
    ld.shared.v2.f32 {%v2, %v3}, [%r_ain+280];
    ld.shared.v4.f32 {%wv0, %wv1, %wv2, %wv3}, [%r_wt+0];
    ld.shared.v4.f32 {%wv4, %wv5, %wv6, %wv7}, [%r_wt+16];
    fma.rn.f32 %a00, %v2, %wv0, %a00;
    fma.rn.f32 %a01, %v2, %wv1, %a01;
    fma.rn.f32 %a02, %v2, %wv2, %a02;
    fma.rn.f32 %a03, %v2, %wv3, %a03;
    fma.rn.f32 %a04, %v2, %wv4, %a04;
    fma.rn.f32 %a05, %v2, %wv5, %a05;
    fma.rn.f32 %a06, %v2, %wv6, %a06;
    fma.rn.f32 %a07, %v2, %wv7, %a07;
    fma.rn.f32 %a10, %v3, %wv0, %a10;
    fma.rn.f32 %a11, %v3, %wv1, %a11;
    fma.rn.f32 %a12, %v3, %wv2, %a12;
    fma.rn.f32 %a13, %v3, %wv3, %a13;
    fma.rn.f32 %a14, %v3, %wv4, %a14;
    fma.rn.f32 %a15, %v3, %wv5, %a15;
    fma.rn.f32 %a16, %v3, %wv6, %a16;
    fma.rn.f32 %a17, %v3, %wv7, %a17;
    ld.shared.v4.f32 {%wv0, %wv1, %wv2, %wv3}, [%r_wt+32];
    ld.shared.v4.f32 {%wv4, %wv5, %wv6, %wv7}, [%r_wt+48];
    fma.rn.f32 %a00, %v1, %wv0, %a00;
    fma.rn.f32 %a01, %v1, %wv1, %a01;
    fma.rn.f32 %a02, %v1, %wv2, %a02;
    fma.rn.f32 %a03, %v1, %wv3, %a03;
    fma.rn.f32 %a04, %v1, %wv4, %a04;
    fma.rn.f32 %a05, %v1, %wv5, %a05;
    fma.rn.f32 %a06, %v1, %wv6, %a06;
    fma.rn.f32 %a07, %v1, %wv7, %a07;
    fma.rn.f32 %a10, %v2, %wv0, %a10;
    fma.rn.f32 %a11, %v2, %wv1, %a11;
    fma.rn.f32 %a12, %v2, %wv2, %a12;
    fma.rn.f32 %a13, %v2, %wv3, %a13;
    fma.rn.f32 %a14, %v2, %wv4, %a14;
    fma.rn.f32 %a15, %v2, %wv5, %a15;
    fma.rn.f32 %a16, %v2, %wv6, %a16;
    fma.rn.f32 %a17, %v2, %wv7, %a17;
    ld.shared.v4.f32 {%wv0, %wv1, %wv2, %wv3}, [%r_wt+64];
    ld.shared.v4.f32 {%wv4, %wv5, %wv6, %wv7}, [%r_wt+80];
    fma.rn.f32 %a00, %v0, %wv0, %a00;
    fma.rn.f32 %a01, %v0, %wv1, %a01;
    fma.rn.f32 %a02, %v0, %wv2, %a02;
    fma.rn.f32 %a03, %v0, %wv3, %a03;
    fma.rn.f32 %a04, %v0, %wv4, %a04;
    fma.rn.f32 %a05, %v0, %wv5, %a05;
    fma.rn.f32 %a06, %v0, %wv6, %a06;
    fma.rn.f32 %a07, %v0, %wv7, %a07;
    fma.rn.f32 %a10, %v1, %wv0, %a10;
    fma.rn.f32 %a11, %v1, %wv1, %a11;
    fma.rn.f32 %a12, %v1, %wv2, %a12;
    fma.rn.f32 %a13, %v1, %wv3, %a13;
    fma.rn.f32 %a14, %v1, %wv4, %a14;
    fma.rn.f32 %a15, %v1, %wv5, %a15;
    fma.rn.f32 %a16, %v1, %wv6, %a16;
    fma.rn.f32 %a17, %v1, %wv7, %a17;
    // ---- ky = 1 (patch row ty+1) ----
    ld.shared.v2.f32 {%v0, %v1}, [%r_ain+136];
    ld.shared.v2.f32 {%v2, %v3}, [%r_ain+144];
    ld.shared.v4.f32 {%wv0, %wv1, %wv2, %wv3}, [%r_wt+96];
    ld.shared.v4.f32 {%wv4, %wv5, %wv6, %wv7}, [%r_wt+112];
